def count_pairs_with_equal_frequencies(values):
    # Count frequency of each value
    freq = {}
    for val in values:
        freq[val] = freq.get(val, 0) + 1

    # Count pairs
    ans = 0
    for count in freq.values():
        ans += count * (count - 1) // 2

    return ans

# Read input
n = int(input())
a = list(map(int, input().split()))

# Calculate f(x) for each number
def f(x):
    if x == 0:
        return 0
    if x % 2 == 0:
        return f(x // 2)
    else:
        return f(x // 2) + 1

# Get frequencies
frequencies = [f(x) for x in a]

# Count pairs
print(count_pairs_with_equal_frequencies(frequencies))
