import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    points = []
    for _ in range(n):
        x = int(next(it))
        y = int(next(it))
        points.append((x, y))

    from collections import defaultdict
    cnt = defaultdict(int)
    for i in range(n):
        xi, yi = points[i]
        for j in range(i + 1, n):
            xj, yj = points[j]
            key = (xi + xj, yi + yj)
            cnt[key] += 1

    res = 0
    for k in cnt.values():
        if k >= 2:
            res += k * (k - 1) // 2
    print(res)

if __name__ == "__main__":
    solve()
"}

