    l = []
    r = []
    for i in range(n):
        li = int(data[1 + 2*i])
        ri = int(data[2 + 2*i])
        l.append(li)
        r.append(ri)

    # Find max_l and second_max_l
    max_l = max(l)
    count_max_l = l.count(max_l)
    second_max_l = -1
    for val in l:
        if val < max_l:
            second_max_l = max(second_max_l, val)

    # Find min_r and second_min_r
    min_r = min(r)
    count_min_r = r.count(min_r)
    second_min_r = 10**9 + 1
    for val in r:
        if val > min_r:
            second_min_r = min(second_min_r, val)

    max_length = 0

    for i in range(n):
        # Calculate new_max_l after removing segment i
        if l[i] == max_l:
            if count_max_l > 1:
                new_max_l = max_l
            else:
                new_max_l = second_max_l
        else:
            new_max_l = max_l

        # Calculate new_min_r after removing segment i
        if r[i] == min_r:
            if count_min_r > 1:
                new_min_r = min_r
            else:
                new_min_r = second_min_r
        else:
            new_min_r = min_r

        # Calculate length
        length = max(0, new_min_r - new_max_l)
        max_length = max(max_length, length)

    print(max_length)

if __name__ == "__main__":
    solve()
