import sys

def is_special(a, val):
    n = len(a)
    # Check all possible starting points
    for l in range(n):
        current_sum = 0
        # Calculate cumulative sum from l to r
        for r in range(l, n):
            current_sum += a[r]
            if current_sum == val:
                return True
            elif current_sum > val:
                break  # No need to continue
    return False

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        special_count = 0

        for val in a:
            if is_special(a, val):
                special_count += 1

        out_lines.append(str(special_count))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

