def solve():
    n, m, k = map(int, input().split())
    board = []
    for _ in range(n):
        board.append(input().strip())

    # Convert to integers
    peas = [[int(board[row][col]) for col in range(m)] for row in range(n)]

    # Target remainder
    target_rem = 0
    divisor = k + 1

    # DP: dp[row][col][rem] = maximum peas collected from (row, col) with remainder rem when reaching the top row
    dp = [[[-1 for _ in range(divisor)] for _ in range(m)] for _ in range(n)]

    # Initialize: top row can only have peas from itself
    for col in range(m):
        val = peas[0][col]
        rem = val % divisor
        dp[0][col][rem] = val

    # Work backwards from top to bottom
    for row in range(1, n):
        for col in range(m):
            # We can come from left (col-1) with move 'L' or right (col+1) with move 'R'
            for move in ['L', 'R']:
                # Determine source column
                if move == 'L':
                    src_col = col - 1
                else:
                    src_col = col + 1

                if 0 <= src_col < m:
                    # Check if we can come from source
                    for rem in range(divisor):
                        if dp[row][col][rem] == -1:
                            continue

                        # Calculate new remainder and total peas
                        src_peas = peas[row][src_col]
                        new_total = dp[row][col][rem] + src_peas
                        new_rem = new_total % divisor

                        # Update if this is better
                        if dp[row][col][rem] > dp[row][col][new_rem] or (dp[row][col][rem] == dp[row][col][new_rem] and new_total > dp[row][col][new_rem]):
                            dp[row][col][new_rem] = new_total

    # Find the best starting position
    max_peas = -1
    best_start_col = -1
    best_path = ""

    # Try each starting column in the lowest row
    for start_col in range(m):
        # We need to trace back from (n-1, start_col)
        cur_row, cur_col = n - 1, start_col
        total = peas[n-1][start_col]
        path = ""

        # Trace back to top row
        for row in range(n-1, 0, -1):
            found = False
            # Try both possible moves
            for move in ['L', 'R']:
                if move == 'L':
                    src_col = cur_col - 1
                else:
                    src_col = cur_col + 1

                if 0 <= src_col < m:
                    # Check if we can come from source with some remainder
                    for rem in range(divisor):
                        if dp[row][cur_col][rem] == -1:
                            continue

                        # Calculate source total
                        src_total = dp[row][cur_col][rem]
                        src_rem = src_total % divisor

                        # Check if this matches our current state
                        if src_rem == (total % divisor):
                            # This is a valid path
                            found = True
                            total = src_total
                            path = move + path
                            cur_row, cur_col = row, src_col
                            break
                    if found:
                        break
            if not found:
                break

        if cur_row == 0 and total % divisor == 0:
