    vector_count = {}
    for i in range(n):
        for j in range(i + 1, n):
            dx = points[j][0] - points[i][0]
            dy = points[j][1] - points[i][1]
            vector = (dx, dy)

            # To avoid double counting vectors, we can store them in a sorted tuple
            # This ensures (dx, dy) and (dy, dx) are treated differently
            vector = (dx, dy)

            vector_count[vector] = vector_count.get(vector, 0) + 1

    # Count number of parallelograms
    parallelograms = 0
    for count in vector_count.values():
        if count >= 2:
            # Number of ways to choose 2 pairs with the same vector
            parallelograms += count * (count - 1) // 2

    print(parallelograms)

