                # Valid sequence from stack[-1]+1 to i
                current_len = i - stack[-1]
                if current_len > max_len:
                    max_len = current_len
                    count = 1
                elif current_len == max_len:
                    count += 1

    if max_len == 0:
        return "0 1"
    else:
        return f"{max_len} {count}"

