import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Count frequency of each element
        freq = {}
        for num in a:
            freq[num] = freq.get(num, 0) + 1

        # Find the element with maximum frequency
        max_freq = max(freq.values())
        candidates = [k for k, v in freq.items() if v == max_freq]

        # For each candidate, count non-candidate contiguous blocks
        min_ops = float('inf')
        for x in candidates:
            count = 0
            i = 0
            while i < n:
                if a[i] != x:
                    count += 1
                    # Skip all contiguous non-x elements
                    while i < n and a[i] != x:
                        i += 1
                else:
                    i += 1
            min_ops = min(min_ops, count)

        print(min_ops)

if __name__ == "__main__":
    solve()
