for _ in range(t):
    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    # Compute square-free parts
    sf = [square_free_part(x) for x in a]

    # Count distinct square-free parts in current segment
    seen = set()
    segments = 0

    for num in sf:
        if num in seen:
            # Start new segment
            seen = {num}
            segments += 1
        else:
            seen.add(num)

    # Add the last segment
    segments += 1

    print(segments)
