def solve():
    n = int(input().strip())

    # Read 4 pieces, skipping empty lines
    pieces = []
    for piece_idx in range(4):
        piece = []
        for _ in range(n):
            line = input()
            while line.strip() == "":
                line = input()
            piece.append(line.strip())
        pieces.append(piece)

        # Skip empty lines, but only if there are more pieces to read
        if piece_idx < 3:
            while True:
                line = input()
                if line.strip() != "":
                    break

    # Now try all 24 arrangements
    # For each arrangement, we need to compute cost

    # Let's precompute for each piece:
    # - for each position (0, 0), (0, n), (n, 0), (n, n)
    #   cost to place in that position with pattern 0 and 1

    # We'll compute a 4x4 matrix of costs: [piece][position][pattern]
    costs = [[[[0] * 2 for _ in range(4)] for _ in range(4)] for _ in range(4)]

    # Precompute for each piece, each position, each pattern
    for piece_idx in range(4):
        piece = pieces[piece_idx]
        for pos in range(4):
            o_row, o_col = (0, 0) if pos == 0 else (0, n) if pos == 1 else (n, 0) if pos == 2 else (n, n)
            for pattern in [0, 1]:
                cost = 0
                for i in range(n):
                    for j in range(n):
                        # Color in piece
                        piece_color = int(piece[i][j])

                        # Should be black?
                        should_be_black = (o_row + i + o_col + j) % 2 == (pattern % 2)

                        # Recolor needed
                        if should_be_black and not piece_color:
                            cost += 1
                        elif not should_be_black and piece_color:
                            cost += 1
                costs[piece_idx][pos][pattern] = cost

    # Now try all 24 arrangements
    min_total = float('inf')

    for perm in range(24):
        # piece_order[0] is position 0, piece_order[1] is position 1, etc.
        piece_order = [0, 1, 2, 3]
        piece_order[0], piece_order[1], piece_order[2], piece_order[3] = divmod(perm, 4), divmod(perm // 4, 4), divmod(perm // 16, 4), divmod(perm // 64, 4)

        # Try both patterns
        for pattern in [0, 1]:
            total = 0
            for pos in range(4):
                total += costs[piece_order[pos]][pos][pattern]

            if total < min_total:
                min_total = total

    print(min_total)

if __name__ == "__main__":
