def solve():
    n, m, k = map(int, input().split())
    board = []
    for _ in range(n):
        board.append(input().strip())

    # Convert board to integer values
    board = [[int(board[i][j]) for j in range(m)] for i in range(n)]

    target = k + 1

    # dp[i][j][r] = (max_peas, path)
    # State: (row, column, remainder) -> (max_peas, path)
    # Start from the bottom row
    dp = [[dict() for _ in range(m)] for _ in range(n)]

    # Initialize bottom row
    for j in range(m):
        peas = board[n-1][j]
        remainder = peas % target
        dp[n-1][j][remainder] = (peas, '')

    # Work up from bottom to top
    for i in range(n-2, -1, -1):
        for j in range(m):
            peas = board[i][j]
            for dj in (-1, 1):
                ni, nj = i + 1, j + dj
                if 0 <= ni < n and 0 <= nj < m:
                    for r, (p, path) in dp[ni][nj].items():
                        new_r = (r + peas) % target
                        new_p = p + peas
                        new_path = path + ('L' if dj == -1 else 'R')

                        if new_r not in dp[i][j] or new_p > dp[i][j][new_r][0]:
                            dp[i][j][new_r] = (new_p, new_path)

    # Find best result in top row
    best_peas = -1
    best_col = -1
    best_path = ''

    for j in range(m):
        if 0 in dp[0][j]:
            peas, path = dp[0][j][0]
            if peas > best_peas:
                best_peas = peas
                best_col = j + 1  # Columns are 1-indexed
                best_path = path

    if best_peas == -1:
        print(-1)
    else:
        print(best_peas)
        print(best_col)
        print(best_path)

