import sys
from collections import Counter

def can_transform(s, t, p):
    # Count characters in s, t, and p
    count_s = Counter(s)
    count_t = Counter(t)
    count_p = Counter(p)

    # Check if we have enough characters in p to cover the difference
    for char in count_t:
        # We need count_t[char] - count_s[char] of this character
        needed = count_t[char] - count_s.get(char, 0)

        # If needed is positive, we need it from p
        if needed > 0:
            if count_p.get(char, 0) < needed:
                return False

    # Also check that we don't need characters that aren't in p
    for char in count_s:
        if count_t.get(char, 0) < count_s[char]:
