def can_reach_sum(arr, target):
    # Compute initial sums
    n = len(arr)
    sums = set()
    left_sums = {}
    right_sums = {}

    # Function to compute sums for a subarray
    def compute_sums(start, end):
        if start > end:
            return set()

        # Get the subarray
        sub = arr[start:end]

        # Compute sum
        total = sum(sub)

        # If we already computed sums for this subarray, return them
        if start in left_sums:
            return left_sums[start] | right_sums[start]

        # Compute mid
        mid = (min(sub) + max(sub)) // 2

        # Split into left and right
        left = []
        right = []
        for num in sub:
            if num <= mid:
                left.append(num)
            else:
                right.append(num)

        # Compute sums for left and right
        left_sums[start] = compute_sums(start, start + len(left))
        right_sums[start] = compute_sums(start + len(left), end)

        # Add the current subarray's sum
        if start == end:
            left_sums[start].add(total)
        else:
            left_sums[start].add(total)
            right_sums[start].add(total)

        return left_sums[start]

    # Compute all possible sums
    all_sums = compute_sums(0, n)

    return target in all_sums

