import sys

def count_bulls_and_cows(secret, guess):
    """Count bulls and cows for a guess"""
    bulls = 0
    cows = 0

    # Count bulls first
    for i in range(4):
        if secret[i] == guess[i]:
            bulls += 1

    # Count cows (digits present but in wrong position)
    secret_digits = set(secret)
    guess_digits = set(guess)

    # Remove bulls from consideration
    for i in range(4):
        if secret[i] == guess[i]:
            secret_digits.remove(secret[i])
            guess_digits.remove(guess[i])

    cows = len(secret_digits & guess_digits)

    return bulls, cows

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    guesses = []
    idx = 1

    for _ in range(n):
        num = data[idx:idx+4]
        num = num[0] + num[1] + num[2] + num[3]
        bulls = int(data[idx+4])
        cows = int(data[idx+5])
        guesses.append((num, bulls, cows))
        idx += 6

    # Generate all valid 4-digit numbers with distinct digits
    valid_numbers = []
    for num in range(10000):
        digits = str(num).zfill(4)
        if len(set(digits)) == 4:
            valid_numbers.append(digits)

    # Filter candidates
    candidates = valid_numbers[:]

    for guess, bulls, cows in guesses:
        new_candidates = []
        for candidate in candidates:
            if bulls == 0 and cows == 0:
                # No bulls and no cows means all digits are wrong
                if not (set(candidate) & set(guess)):
                    new_candidates.append(candidate)
            else:
                # Check if this candidate matches the bulls and cows
                cnt_bulls, cnt_cows = count_bulls_and_cows(candidate, guess)
                if cnt_bulls == bulls and cnt_cows == cows:
                    new_candidates.append(candidate)

        candidates = new_candidates

        if not candidates:
            break

    if not candidates:
        print("Incorrect data")
    elif len(candidates) == 1:
        print(candidates[0])
    else:
        print("Need more data")

if __name__ == "__main__":
    solve()
