import math

def tram_time_to_reach(x, p, d, s, t1):
    """Calculate the time for the tram to reach position x"""
    if d == 1:
        # Forward direction
        if x >= p:
            return t1 * (x - p)
        elif x < p:
            # Tram reaches 0 first, then turns around
            return t1 * (2 * p - x)
        else:  # x > s
            # Tram reaches s first, then turns around
            return t1 * (2 * s - p - x)
    else:  # d == -1
        # Backward direction
        if x <= p:
            return t1 * (p - x)
        else:  # x > p
            # Tram reaches 0 first, then turns around
            return t1 * (x + p)

def solve() -> None:
    s, x1, x2 = map(int, input().split())
    t1, t2 = map(int, input().split())
    p, d = map(int, input().split())

    # Direct walking time
    walk_time = abs(x2 - x1) * t2

    # Tram time from x1 to x2 directly
    tram_time = abs(x2 - x1) * t1

    # Minimum time considering boarding
    min_time = min(walk_time, tram_time)

    # Consider boarding at each position between 0 and s
    for x in range(0, s + 1):
        # Time for Igor to reach boarding point x
        time_to_reach = abs(x - x1) * t2

        # Time for tram to reach boarding point x
        time_to_tram = tram_time_to_reach(x, p, d, s, t1)

        # Time to ride from x to x2 on the tram
        time_on_tram = abs(x2 - x) * t1

        # Total time
        total_time = time_to_reach + time_to_tram + time_on_tram

        min_time = min(min_time, total_time)

    print(min_time)

if __name__ == "__main__":
    solve()
