# Precompute palindrome counts for each substring
n = 0
palindrome_counts = []

def compute_palindromes(s):
    count = 0
    n = len(s)

    for length in range(1, n + 1):
        for start in range(n - length + 1):
            substr = s[start:start+length]
            if substr == substr[::-1]:
                count += 1
    return count

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    s = data[0]
    n = len(s)

    # Precompute palindrome counts for each substring
    for length in range(1, n + 1):
        for start in range(n - length + 1):
            substr = s[start:start+length]
            if substr == substr[::-1]:
                palindrome_counts.append((start, length))

    q = int(data[1])
    queries = [(int(data[i*2+2]), int(data[i*2+3])) for i in range(q)]

    output = []
    for L, R in queries:
        count = 0
        # Convert 1-indexed to 0-indexed
        L -= 1
        R -= 1

        # Count palindromes that fit in the range
        for start, length in palindrome_counts:
            if L <= start and start + length <= R:
                count += 1

        output.append(str(count))

    sys.stdout.write(' '.join(output))

if __name__ == "__main__":
    solve()
