    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    matrix = []
    idx = 1
    for _ in range(n):
        row = data[idx]
        matrix.append([int(ch) for ch in row])
        idx += 1

    print("n =", n)
    for i in range(n):
        print(f"row {i}:", " ".join(str(val) for val in matrix[i]))

    # Check for a directed triangle (cycle of length 3)
    for i in range(n):
        out_neighbors = [j for j in range(n) if matrix[i][j] == 1]
        # Try all pairs of out-neighbors
        for k in range(len(out_neighbors)):
            for l in range(k + 1, len(out_neighbors)):
                b = out_neighbors[k]
                c = out_neighbors[l]
                # Check if there's an edge from b to c or from c to b
                if matrix[b][c] == 1:
                    print(f"{i+1} {b+1} {c+1}")
                    return
                elif matrix[c][b] == 1:
                    print(f"{i+1} {c+1} {b+1}")
                    return

    print("-1")

if __name__ == "__main__":
    solve()
"}

