        # Actually balance = previous balance + 1 if '(', -1 if ')' ?
        # Use cumulative balance:
        # Actually we can use balance = [0] * (n + 1)

    # Correct algorithm:
    # Let's use balance array
    balance = [0] * (n + 1)
    for i in range(1, n + 1):
