import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Read n strings
    strings = set()
    for _ in range(n):
        s = next(it)
        strings.add(s)

    # Build a dictionary: string -> length
    string_to_len = {}
    for s in strings:
        string_to_len[s] = len(s)

    # Build a dictionary: length -> set of strings
    len_to_strings = {}
    for s in strings:
        l = len(s)
        if l not in len_to_strings:
            len_to_strings[l] = set()
        len_to_strings[l].add(s)

    # For each query, check if any variant exists
    out_lines = []
    for _ in range(m):
        query = next(it)
        l = len(query)

        # Check if there's a string of the same length
        if l not in len_to_strings:
            out_lines.append("NO")
            continue

        # Check if any variant of query exists
        found = False
        for i in range(l):
            # Change character at position i to 'a', 'b', or 'c'
            # But we need to differ in exactly one position, so we need to check all possibilities
            for c in ['a', 'b', 'c']:
                if c == query[i]:
                    continue  # Skip the original character

                # Create variant
                variant = query[:i] + c + query[i+1:]

                # Check if this variant exists
                if variant in strings:
                    found = True
                    break
            if found:
                break

        out_lines.append("YES" if found else "NO")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

