def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    points = []
    idx = 1

    for _ in range(n):
        x = int(data[idx])
        y = int(data[idx + 1])
        points.append((x, y))
        idx += 2

    # Count pairs with the same sum
    count = {}

    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = points[i]
            x2, y2 = points[j]
            key = (x1 + x2, y1 + y2)

            if key in count:
                count[key] += 1
            else:
                count[key] = 1

    # Calculate number of parallelograms
    result = 0
    for k in count.values():
        result += k * (k - 1) // 2

