def is_consistent(target, guess, bulls, cows):
    """Check if a target number is consistent with a guess."""
    target_digits = list(target)
    guess_digits = list(guess)

    # Count bulls
    bull_count = 0
    for i in range(4):
        if target_digits[i] == guess_digits[i]:
            bull_count += 1

    # Count cows
    cow_count = 0
    # Check each digit in the guess
    for i in range(4):
        if target_digits[i] == guess_digits[i]:
            continue  # Skip bulls
        # Check if this digit is present in the target (excluding bulls)
        if guess_digits[i] in target_digits:
            cow_count += 1

