    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        p = [int(next(it)) for _ in range(n)]

        # Create position map: value -> position (1-indexed)
        pos = {}
        for i in range(n):
            val = p[i]
            pos[val] = i + 1  # Positions are 1-indexed

        result = []
        for m in range(1, n + 1):
            # Get positions of all values from 1 to m
            positions = [pos[val] for val in range(1, m + 1)]
            min_pos = min(positions)
            max_pos = max(positions)

            if max_pos - min_pos == m - 1:
                result.append('1')
            else:
                result.append('0')

        out_lines.append(''.join(result))

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
