import sys
from collections import defaultdict

def factorize(n):
    factors = defaultdict(int)
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] += 1
            n //= i
        i += 1
    if n > 1:
        factors[n] += 1
    return factors

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Factorize k
    prime_factors = factorize(k)
    if not prime_factors:
        print(0)
        return

    # For each prime factor, compute prefix sums
    prefix = {}
    for p in prime_factors:
        prefix[p] = [0] * (n + 1)
        for i in range(n):
            prefix[p][i+1] = prefix[p][i] + (a[i] % p != 0)

    # Count valid subarrays
    valid_subarrays = 0

    for l in range(n):
        for r in range(l, n):
            # Check if subarray [l, r] is valid
            valid = True
            for p in prime_factors:
                needed = prime_factors[p]
                # Count of p in subarray [l, r]
                count = prefix[p][r+1] - prefix[p][l]
                if count < needed:
                    valid = False
                    break
            if valid:
                valid_subarrays += 1

    print(valid_subarrays)

