def solve():
    # Precompute smallest prime factors
    max_val = 10**7 + 1
    spf = list(range(max_val))
    for i in range(2, int(max_val**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_val, i):
                if spf[j] == j:
                    spf[j] = i

    def square_free(n):
        # Divide out all perfect square factors
        # We can just keep dividing by the smallest prime factor
        # until n becomes square-free
        result = 1
        i = 2
        while n > 1:
            p = spf[n]
            if p * p <= n:
                # Divide out all occurrences of p
                while n % p == 0:
                    n //= p
                result *= p
            else:
                # p^2 > n, so n is square-free
                break
        return result

    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))

        # Compute square-free representations
        square_free_a = [square_free(x) for x in a]

        # Count segments
        segments = 0
        seen = {}

        for num in square_free_a:
            if num in seen:
                # We need to start a new segment
                segments += 1
                seen = {num: True}
            else:
                seen[num] = True

        # Add the last segment
        segments += 1

        print(segments)

solve()
