# Manacher's algorithm to find all palindromic substrings
# We'll use a 2D DP where dp[i][j] = 1 if s[i:j+1] is a palindrome
s = input().strip()
q = int(input())
queries = []
for _ in range(q):
    l, r = map(int, input().split())
    queries.append((l, r))

n = len(s)
dp = [[0] * n for _ in range(n)]

# Initialize single characters
for i in range(n):
    dp[i][i] = 1

# Check for palindromes of length 2
for i in range(n - 1):
    if s[i] == s[i + 1]:
        dp[i][i + 1] = 1

# Check for palindromes of length > 2
for length in range(3, n + 1):
    for i in range(n - length + 1):
        j = i + length - 1
        if s[i] == s[j] and dp[i + 1][j - 1]:
            dp[i][j] = 1

# Count palindromes
palindromes = []
for i in range(n):
    for j in range(i, n):
        if dp[i][j]:
            palindromes.append((i + 1, j + 1))  # 1-indexed

# Process queries
results = []
for l, r in queries:
    count = 0
    for start, end in palindromes:
        if l <= start <= end <= r:
            count += 1
    results.append(str(count))

print(' '.join(results))
"}

