    for i in range(n):
        row = []
        for j in range(n):
            row.append(int(data[idx]))
            idx += 1
        matrix.append(row)

    # For each vertex i, look at its out-neighbors and in-neighbors
    for i in range(n):
        # Find out-neighbors (j where matrix[i][j] == 1)
        out_neighbors = []
        for j in range(n):
            if matrix[i][j] == 1:
                out_neighbors.append(j)

        # Check if any two out-neighbors have an edge between them
        for j in range(len(out_neighbors)):
            for k in range(j + 1, len(out_neighbors)):
                if matrix[out_neighbors[j]][out_neighbors[k]] == 1:
                    # Cycle: i->j, j->k, k->i
                    print(f"{i + 1} {out_neighbors[j] + 1} {out_neighbors[k] + 1}")
                    return

        # Find in-neighbors (j where matrix[j][i] == 1)
        in_neighbors = []
        for j in range(n):
            if matrix[j][i] == 1:
                in_neighbors.append(j)

