MOD = 1000000007

n, m = map(int, input().split())

# dp[i] = number of ways to reach stop i
# dp[0] = 1
# For each stop i, dp[i] = sum(dp[j] for all j < i such that there's a bus from j to i)

# Instead of using an array of size n+1 (which is too large), we can use a dictionary
# to store only the stops that have buses ending at them

# Create a dictionary: key = stop number, value = list of buses ending at that stop
end_at = {}

for _ in range(m):
    s, t = map(int, input().split())
    if t not in end_at:
        end_at[t] = []
    end_at[t].append(s)

# dp[i] = number of ways to reach stop i
# We'll use a dictionary to store only reachable stops
dp = {0: 1}

for i in range(1, n + 1):
    if i in end_at:
        # There are buses ending at i
        # dp[i] = sum(dp[s] for all s that can reach i)
        total = 0
        for s in end_at[i]:
            if s in dp:
                total = (total + dp[s]) % MOD
        dp[i] = total
    else:
        # No buses end at i
        dp[i] = 0

print(dp.get(n, 0) % MOD)
