        pos_one = p.index(1)

        result = ['0'] * n

        for i in range(n):
            val = p[i]
            m = val
            if m == 1:
                # Always beautiful, just the position of 1
                result[i] = '1'
            else:
                # Check if 1 is in the subarray ending at i with length m
                # Subarray starts at i-m+1 and ends at i-1 (since we need to check before i)
                start = i - m + 1
                if start >= 0 and start <= i - 1:
                    if start <= pos_one <= i - 1:
                        result[i] = '1'

        out_lines.append(''.join(result))

