import heapq

def solve():
    n, s, k = map(int, input().split())
    r = list(map(int, input().split()))
    c = input().strip()

    # State: (position, last_color, last_count, candies_eaten, time)
    # Use a priority queue sorted by time
    pq = []
    heapq.heappush(pq, (0, s-1, -1, 0, 0))  # (time, position, last_color, candies_eaten)

    visited = {}

    colors = {'R': 0, 'G': 1, 'B': 2}

    while pq:
        time, pos, last_color, candies = heapq.heappop(pq)

        # If we've already found a better path to this state, skip
        state = (pos, last_color, candies)
        if state in visited:
            if visited[state] <= time:
                continue
        visited[state] = time

        # If we've eaten enough candies, return the time
        if candies >= k:
            return time

        # Option 1: Move to adjacent boxes
