import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    edges = [[] for _ in range(n + 1)]
    idx = 1

    for _ in range(n - 1):
        a = int(data[idx])
        b = int(data[idx + 1])
        edges[a].append(b)
        edges[b].append(a)
        idx += 2

    # Find leaves (degree 1)
    leaves = [i for i in range(1, n + 1) if len(edges[i]) == 1]

    # Check if all leaves have the same parity from some node
    def same_parity(start, leaves):
        dist = [-1] * (n + 1)
        dist[start] = 0

        from collections import deque
        q = deque([start])

        while q:
            u = q.popleft()
            for v in edges[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)

        # Check if all leaves have the same parity
        for leaf in leaves:
            if dist[leaf] == -1:
                return False  # Not reachable (shouldn't happen in tree)
        return dist[leaves[0]] % 2 == 0 and all(dist[leaf] % 2 == 0 for leaf in leaves)

    # Check if there exists a root where all leaves have the same parity
    has_same_parity = False
    for leaf in leaves:
        if same_parity(leaf, leaves):
            has_same_parity = True
            break

    min_f = 1 if has_same_parity else 2
    max_f = n - 1

    print(min_f, max_f)

if __name__ == "__main__":
    solve()
