import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = int(next(it))
    b = int(next(it))
    seals = []
    for _ in range(n):
        x = int(next(it))
        y = int(next(it))
        seals.append((x, y))

    max_area = 0

    if n >= 2:
        for i in range(n):
            x1, y1 = seals[i]
            for j in range(i + 1, n):
                x2, y2 = seals[j]

                # Check if both individually fit on paper
                fits1 = (x1 <= a and y1 <= b) or (x1 <= b and y1 <= a)
                fits2 = (x2 <= a and y2 <= b) or (x2 <= b and y2 <= a)
                if not fits1 or not fits2:
                    continue

                # Try all orientation pairs for both seals
                for rot1 in [0, 1]:
                    for rot2 in [0, 1]:
                        w1, h1 = (x1, y1) if rot1 == 0 else (y1, x1)
                        w2, h2 = (x2, y2) if rot2 == 0 else (y2, x2)

                        # Check if they fit side by side horizontally: sum widths <= a, max heights <= b
                        if w1 + w2 <= a and max(h1, h2) <= b:
                            area = w1 * h1 + w2 * h2
                            if area > max_area:
                                max_area = area
                        # Check side by side vertically: sum heights <= b, max widths <= a
                        if h1 + h2 <= b and max(w1, w2) <= a:
                            area = w1 * h1 + w2 * h2
                            if area > max_area:
                                max_area = area

    print(max_area)

if __name__ == "__main__":
    solve()
