import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        min_ops = n  # maximum possible operations

        # Try each possible value of x
        for x in set(a):
            blocks = 0
            i = 0
            while i < n:
                if a[i] != x:
                    # Start of a block of non-x elements
                    blocks += 1
                    # Find end of this block
                    while i < n and a[i] != x:
                        i += 1
                else:
                    # Skip over x elements
                    while i < n and a[i] == x:
                        i += 1

            min_ops = min(min_ops, blocks)

        print(min_ops)

if __name__ == "__main__":
    solve()
"}

