import sys

def can_place(w1, h1, w2, h2, a, b):
    """Check if two rectangles can be placed on a paper of size a × b"""
    # Try horizontal placement: side by side
    if w1 + w2 <= a and max(h1, h2) <= b:
        return True

    # Try vertical placement: one above the other
    if max(w1, w2) <= a and h1 + h2 <= b:
        return True

    return False

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = int(data[1])
    b = int(data[2])

    seals = []
    idx = 3
    for _ in range(n):
        x = int(data[idx])
        y = int(data[idx + 1])
        seals.append((x, y))
        idx += 2

    max_area = 0

    # Try all pairs of seals
    for i in range(n):
        for j in range(i + 1, n):
            # Try all 4 combinations of rotations
            for w1, h1 in [(seals[i][0], seals[i][1]), (seals[i][1], seals[i][0])]:
                for w2, h2 in [(seals[j][0], seals[j][1]), (seals[j][1], seals[j][0])]:
                    if can_place(w1, h1, w2, h2, a, b):
                        area = w1 * h1 + w2 * h2
                        if area > max_area:
                            max_area = area

    print(max_area)

if __name__ == "__main__":
    solve()
